VALUES
('florist-biophilia-blooms', 'florist-biophilia-blooms', 'Biophilia Blooms', 'Florist', 'Rushcutters Bay, Sydney NSW', '3 Holdsworth Avenue, Rushcutters Bay NSW 2011', 'https://www.biophiliablooms.com/', '0435 361 644', 'josie@biophiliablooms.com', 'https://www.biophiliablooms.com/', 'Florist website', '2026-11-06', 'active', 'Boutique wedding and event florist in Rushcutters Bay run by Josie Marc. Designs are seasonal and foam-free, with a prop hire range and custom stationery on the side. Travels to the Southern Highlands, Blue Mountains and Hunter Valley and takes some destination weddings.', '{"source":"florists_import_2026_11_06","instagram_url":"https://www.instagram.com/biophiliablooms/","price_note":"No prices published; quote after an email reply within 48 hours or a 15-minute discovery call.","price_from_aud":null,"price_status":null,"contact_basis":"own_site"}'::jsonb, ARRAY['address_conflict_darlinghurst_in_directories']::text[]),
('florist-e-squared-design-co', 'florist-e-squared-design-co', 'E Squared Design Co', 'Florist', 'Sydney NSW', NULL, 'https://www.esquareddesignco.com/', '0415 550 172', 'hello@esquareddesignco.com', 'https://www.esquareddesignco.com/contact-us', 'Florist website', '2026-11-06', 'active', 'Sydney wedding and event florist led by Libby, offering bespoke floristry with full-service styling and concept creation. Works by appointment only and pairs flowers with food and event design for larger celebrations.', '{"source":"florists_import_2026_11_06","instagram_url":"https://www.instagram.com/esquareddesignco/","price_note":"No prices published.","price_from_aud":null,"price_status":null,"contact_basis":"own_site"}'::jsonb, ARRAY['no_street_address','older_directory_listing_says_manly']::text[]),
('florist-jewel-phon-flowers', 'florist-jewel-phon-flowers', 'Jewel Phon Flowers', 'Florist', 'Silverwater, Sydney NSW', '2/20-30 Stubbs Street, Silverwater NSW 2128', 'https://www.jewelphonflowers.com.au/', '0432 089 612', 'jewelphonflowers@gmail.com', 'https://www.jewelphonflowers.com.au/', 'Florist website', '2026-11-06', 'active', 'Floral and event stylist with a Silverwater studio and a large stock of hire decor. Leans luxe and bespoke, and says it has designed Sydney weddings for more than 21 years. Visits are by appointment.', '{"source":"florists_import_2026_11_06","instagram_url":"https://www.instagram.com/jewelphonflowers/","price_note":"No prices published.","price_from_aud":null,"price_status":null,"contact_basis":"own_site"}'::jsonb, ARRAY['address_conflict_lidcombe_in_page_title','experience_years_differs_in_directories']::text[]),
('florist-anna-wang-stylist', 'florist-anna-wang-stylist', 'Anna Wang Stylist', 'Florist', 'Sydney NSW', NULL, 'https://annawangstylist.com.au/', '+61 406 420 166', 'anna@annawang.au', 'https://annawangstylist.com.au/', 'Florist website', '2026-11-06', 'active', 'Luxury wedding stylist that designs and builds its own florals rather than subcontracting. Known for arbours, flower walls and ceiling installations, plus bouquets and buttonholes. Showroom visits by appointment and long lead times.', '{"source":"florists_import_2026_11_06","instagram_url":"https://www.instagram.com/annawangstylist/","price_note":"No styling fee on top of pieces and florals; 40% deposit. Most couples book 8-14 months ahead.","price_from_aud":null,"price_status":null,"contact_basis":"own_site"}'::jsonb, ARRAY['no_street_address','two_domains_annawang_au_and_annawang_com_au','mixed_third_party_reviews']::text[]),
('florist-nunu-designs', 'florist-nunu-designs', 'Nunu Designs', 'Florist', 'Sutherland Shire, Sydney NSW', NULL, 'https://www.nunudesigns.com.au/', NULL, 'hello@nunudesigns.com.au', 'https://www.nunudesigns.com.au/weddings', 'Florist website', '2026-11-06', 'active', 'Luxe wedding and event florist in southern Sydney run by Steph Jordan, known for hanging and large impact installations. Couples fill in an online consultation, get a price guide, then an itemised quote with a mood board. Travels to the Hunter, South Coast and Southern Highlands.', '{"source":"florists_import_2026_11_06","instagram_url":"https://www.instagram.com/nunuau/","price_note":"Wedding florals from $6,000 per the studio''s site (a directory shows $3,000, likely outdated); 20% deposit locks the date.","price_from_aud":6000,"price_status":"estimated","contact_basis":"own_site"}'::jsonb, ARRAY['needs_contact_lookup','phone_missing','no_street_address','price_from_search_summary']::text[]),
('florist-elodies-blooms-and-botanics', 'florist-elodies-blooms-and-botanics', 'Elodie''s Blooms & Botanics', 'Florist', 'Camden, South-West Sydney NSW', 'Shop 5, 180-186 Argyle Street, Camden NSW 2570', 'https://www.elodies.au/', '02 4655 3285', 'hello@elodies.au', 'https://www.elodies.au/weddings', 'Florist website', '2026-11-06', 'active', 'Camden florist and wedding studio led by Kerryn, doing fully custom, itemised wedding florals with optional styling hire and on-the-day coordination. Wants enquiries up to 18 months ahead and works across south-west Sydney, the Highlands, Blue Mountains and further.', '{"source":"florists_import_2026_11_06","instagram_url":"https://www.instagram.com/bloomsby_elodie/","price_note":"Custom itemised quotes only (no packages); minimum spend $5,000 plus GST, smaller events considered; 50% deposit; quote within 72 hours of meeting.","price_from_aud":5000,"price_status":"estimated","contact_basis":"own_site"}'::jsonb, ARRAY['outer_sydney_camden','price_from_search_summary']::text[]),
('florist-architecture-in-bloom', 'florist-architecture-in-bloom', 'Architecture in Bloom', 'Florist', 'North Kellyville, Sydney NSW', NULL, 'https://architectureinbloom.au/', '0414 872 204', 'admin@architectureinbloom.au', 'https://architectureinbloom.au/contact/', 'Florist website', '2026-11-06', 'active', 'Custom florist in Sydney''s Hills District led by Simone Bennett, doing modern, statement florals from bouquets to large installations. Delivers up to 60km from the studio and travels for weddings across NSW. Site mentions a winter closure.', '{"source":"florists_import_2026_11_06","instagram_url":"https://www.instagram.com/architectureinbloom/","price_note":"Bouquets from $90 on the homepage; wedding quotes depend on scope.","price_from_aud":null,"price_status":null,"contact_basis":"own_site"}'::jsonb, ARRAY['po_box_only_rouse_hill_2155','no_street_address','verify_availability']::text[]),
('florist-japonica', 'florist-japonica', 'Japonica', 'Florist', 'Ryde, Sydney NSW', NULL, 'https://japonica.com.au/', '0404 466 093', 'florals@japonica.com.au', 'https://japonica.com.au/enquire/', 'Florist website', '2026-11-06', 'active', 'Garden-style wedding florist in Ryde with over ten years of weddings. Chooses flowers by what is freshest that week, for textured, slightly wild designs. Publishes weekday and weekend minimum spends and is a preferred florist at Athol Hall.', '{"source":"florists_import_2026_11_06","instagram_url":"https://www.instagram.com/__japonica__/","price_note":"Minimum spend $1,500 (Wed-Fri) or $3,000 (Sat-Sun) excluding delivery.","price_from_aud":3000,"price_status":"estimated","contact_basis":"own_site"}'::jsonb, ARRAY['no_street_address','directory_lists_collaroy_unverified']::text[]),
('florist-floral-fix', 'florist-floral-fix', 'Floral Fix', 'Florist', 'Cronulla, Sydney NSW', 'Peregrine Drive, Cronulla NSW 2230', 'https://www.floralfix.com.au/', NULL, 'flowers@floralfix.com.au', 'https://www.floralfix.com.au/wedding-flowers-sydney.html', 'Florist website', '2026-11-06', 'active', 'Cronulla studio doing loose, romantic seasonal flowers through two routes: ordered-online bridal party packages, or fully bespoke work for ceiling and ceremony pieces. Studio is by appointment; the site says to book four to six months ahead.', '{"source":"florists_import_2026_11_06","instagram_url":"https://www.instagram.com/floral_fix/","price_note":"Online packages plus bespoke design; $200 non-refundable booking fee; balance a month before; 28-day minimum lead on packages.","price_from_aud":null,"price_status":null,"contact_basis":"own_site"}'::jsonb, ARRAY['needs_contact_lookup','phone_missing','no_street_number']::text[]),
('florist-fable-studio-co', 'florist-fable-studio-co', 'Fable Studio Co', 'Florist', 'Alexandria, Sydney NSW', 'Unit 25, 110-116 Bourke Road, Alexandria NSW 2015', 'https://www.fablestudioco.com.au/', '0425 811 468', 'info@fablestudioco.com.au', 'https://www.fablestudioco.com.au/weddinghome', 'Florist website', '2026-11-06', 'active', 'Wedding styling and planning business with its own florists, run by an interior designer and a florist, and open to floral-only bookings. Handles bump-in and bump-out on the day and has worked at the Royal Botanic Garden and Gunners Barracks.', '{"source":"florists_import_2026_11_06","instagram_url":"https://www.instagram.com/fablestudioco/","price_note":"No prices published.","price_from_aud":null,"price_status":null,"contact_basis":"own_site"}'::jsonb, ARRAY['address_conflict_mascot_in_schema','planner_and_florist']::text[]),
('florist-glossie-studio', 'florist-glossie-studio', 'Glossie Studio', 'Florist', 'Dee Why, Northern Beaches NSW', '105 Pacific Parade, Dee Why NSW 2099', 'https://www.glossiegals.com/', '+61 412 531 117', 'admin@glossiegals.com', 'https://www.glossiegals.com/events', 'Florist website', '2026-11-06', 'active', 'Northern Beaches florist doing bold, sculptural wedding flowers across Sydney. Planning starts with a 30-45 minute video consultation, then a custom concept and quote. Covers bouquets, buttonholes, ceremony styling and reception florals.', '{"source":"florists_import_2026_11_06","instagram_url":"https://www.instagram.com/glossiestudios/","price_note":"No prices published; quote follows a 30-45 minute video consultation.","price_from_aud":null,"price_status":null,"contact_basis":"own_site"}'::jsonb, ARRAY['domain_is_glossiegals_not_glossiestudio']::text[]),
('florist-florisian-floral-design', 'florist-florisian-floral-design', 'Florisian Floral Design', 'Florist', 'Baulkham Hills, Sydney NSW', '92 Baulkham Hills Road, Baulkham Hills NSW 2153', 'https://florisianfloraldesign.com.au/', '0488 646 998', 'info@florisian.com.au', 'https://florisianfloraldesign.com.au/about/', 'Florist website', '2026-11-06', 'active', 'Baulkham Hills studio doing upscale wedding florals, from bridal party flowers to larger installations. Delivery, set-up and pack-down are included Sydney-wide, with arches and stands for hire. Visits by appointment.', '{"source":"florists_import_2026_11_06","instagram_url":"https://www.instagram.com/florisian_floral_design/","price_note":"Free quote on request; no prices published.","price_from_aud":null,"price_status":null,"contact_basis":"own_site"}'::jsonb, ARRAY['address_from_search_result','years_from_review_site']::text[]),
('florist-chiho-kobayashi-flowers', 'florist-chiho-kobayashi-flowers', 'Chiho Kobayashi Flowers', 'Florist', 'Ermington, Sydney NSW', NULL, 'https://www.kobayashiflowers.com/', '0424 470 684', 'info@kobayashiflowers.com', 'https://www.kobayashiflowers.com/about', 'Florist website', '2026-11-06', 'active', 'Appointment-only floral studio in Ermington with a background in ikebana and European bouquet styles. Reviews on the site praise colour matching and flexibility with budget. Portfolio includes Gunners Barracks and Watersedge.', '{"source":"florists_import_2026_11_06","instagram_url":"https://www.instagram.com/kobayashiflowers/","price_note":"No prices published; consultations and quotes by appointment.","price_from_aud":null,"price_status":null,"contact_basis":"own_site"}'::jsonb, ARRAY['no_street_address','experience_years_differs_across_pages','site_footer_email_typo_flowres_ignored']::text[]),
('florist-flowers-and-styling-by-felicia', 'florist-flowers-and-styling-by-felicia', 'Flowers and Styling by Felicia', 'Florist', 'Sydney-wide NSW', NULL, 'https://flowersandstyling.com.au/', '0478 647 000', 'info@flowersandstyling.com.au', 'https://flowersandstyling.com.au/about-us/', 'Florist website', '2026-11-06', 'active', 'Florist and stylist run by Felicia Sarwono, with a strong focus on Indian, Desi and Asian weddings. Makes bouquets, arches, hanging installations and flower walls in house, with delivery, set-up and pack-down. Offers preset packages or a bespoke design.', '{"source":"florists_import_2026_11_06","instagram_url":"https://www.instagram.com/flowers_and_styling/","price_note":"Three preset options or bespoke; directory prices conflict ($625 vs $1,500 / $3,000 / $4,500 est.), none confirmed on own site.","price_from_aud":null,"price_status":null,"contact_basis":"own_site"}'::jsonb, ARRAY['no_street_address','directory_locations_conflict_coogee_sylvania_the_ponds','price_conflict_directories']::text[]),
('florist-copper-beech-the-flower-merchant', 'florist-copper-beech-the-flower-merchant', 'Copper Beech, The Flower Merchant', 'Florist', 'Balgowlah, Northern Beaches NSW', '70 Wanganella Street, Balgowlah NSW 2093', 'https://www.copperbeech.com.au/', '(02) 8964 1751', 'hello@copperbeech.com.au', 'https://www.copperbeech.com.au/aboutus/', 'Florist website', '2026-11-06', 'active', 'Northern Beaches flower shop in Balgowlah with a wedding service run by two partners. Offers consultations in store, by phone, at the venue or online, and builds a concept from the first meeting. Works across the North Shore, CBD and Hunter Valley.', '{"source":"florists_import_2026_11_06","instagram_url":"https://www.instagram.com/copper_beech/","price_note":"One listed package at about $4,200; consultations in store, by phone, at the venue or online.","price_from_aud":null,"price_status":null,"contact_basis":"own_site"}'::jsonb, ARRAY['postcode_2097_on_page_text_vs_2093_in_schema','price_from_search_summary','retail_florist_with_weddings']::text[]),
('florist-ally-bell-floral-design', 'florist-ally-bell-floral-design', 'Ally Bell Floral Design', 'Florist', 'Balmain, Inner West Sydney NSW', '493B Darling Street, Balmain NSW 2041', 'https://allybell.com.au/', '0402 998 992', NULL, 'https://allybell.com.au/pages/wedding-florist-sydney', 'Florist website', '2026-11-06', 'active', 'Balmain florist doing bridal bouquets, ceremony arrangements and bespoke event florals, from first consultation to set-up. One of few Sydney florists to publish guideline prices per item. Retail shop open most days.', '{"source":"florists_import_2026_11_06","instagram_url":"https://www.instagram.com/allybellfloraldesign/","price_note":"Guideline prices published: bridal bouquet $150-$450, bridesmaid $120-$250, buttonhole $35, aisle ends $150-$350, table centres $85-$250; florals-led weddings from about $8,000; minimum spends vary by season.","price_from_aud":null,"price_status":null,"contact_basis":"own_site"}'::jsonb, ARRAY['needs_contact_lookup','email_missing','price_from_search_summary','retail_florist_with_weddings']::text[]),
('florist-ls-flower-design', 'florist-ls-flower-design', 'LS Flower Design', 'Florist', 'West Ryde, Sydney NSW', '61a Ryedale Road, West Ryde NSW 2114', 'https://www.lsflowerdesign.com.au/', '0424 593 979', 'info@lsflowerdesign.com.au', 'https://www.lsflowerdesign.com.au/product-category/weddings/', 'Florist website', '2026-11-06', 'active', 'Family-run florist run by two sisters in West Ryde, with a wedding and event service from bridal bouquets to church flowers. Directories describe it as an affordable option. A second mobile number, 0426 763 979, is also listed.', '{"source":"florists_import_2026_11_06","instagram_url":"https://www.instagram.com/lsflowerdesign/","price_note":"No wedding prices published.","price_from_aud":null,"price_status":null,"contact_basis":"own_site"}'::jsonb, ARRAY['retail_florist_with_weddings','template_placeholder_email_ignored']::text[]),
