('florist-fionas-floral-designs', 'florist-fionas-floral-designs', 'Fiona''s Floral Designs', 'Florist', 'Mays Hill, Western Sydney NSW', '21 Napier Street, Mays Hill NSW 2145', 'https://www.fionasfloraldesigns.com.au/', '+61 426 546 469', 'fiona.stellino@fionasfloraldesigns.com.au', 'https://www.fionasfloraldesigns.com.au/', 'Florist website', '2026-11-06', 'active', 'Western Sydney florist for weddings and events that also runs floral workshops and photo booth hire. Serves Greater Sydney and travels to the Blue Mountains, Central Coast, Hunter and South Coast.', '{"source":"florists_import_2026_11_06","instagram_url":null,"price_note":"No prices published.","price_from_aud":null,"price_status":null,"contact_basis":"own_site"}'::jsonb, ARRAY['named_person_email','address_may_be_home_studio']::text[]),
