('florist-the-bloom-folk', 'florist-the-bloom-folk', 'The Bloom Folk', 'Florist', 'Hunter Valley and Central Coast NSW', NULL, 'https://www.thebloomfolk.com.au/', '0411 803 320', 'hello.thebloomfolk@gmail.com', 'https://www.thebloomfolk.com.au/', 'Florist website', '2026-11-06', 'active', 'Wedding florist and styling collective based in the Hunter Valley that also travels to Sydney, the Northern Beaches and Southern Highlands. Garden-inspired, romantic florals with signage and styling. Full-service enquiries go through the website.', '{"source":"florists_import_2026_11_06","instagram_url":"https://www.instagram.com/thebloomfolk/","price_note":"A third-party guide quotes a minimum of $4,500 (Sep-Apr) and $3,500 (winter) with delivery and travel included; not confirmed on the studio''s site.","price_from_aud":null,"price_status":null,"contact_basis":"own_site"}'::jsonb, ARRAY['outside_sydney_base_hunter_valley','no_street_address','price_unconfirmed_third_party']::text[]),
