('florist-form-over-function', 'florist-form-over-function', 'Form Over Function', 'Florist', 'Surry Hills, Sydney NSW', NULL, 'https://formoverfunction.com.au/', '02 9328 6541', NULL, 'https://formoverfunction.com.au/faq/', 'Florist website', '2026-11-06', 'active', 'Boutique event planning company with its own floral team and a large cool room, doing full-service planning and styling. Styling clients must also book its flowers, and it rarely takes more than one event a day.', '{"source":"florists_import_2026_11_06","instagram_url":"https://www.instagram.com/formoverfunctionevents/","price_note":"No prices read. Takes styling clients only if they also book its florals.","price_from_aud":null,"price_status":null,"contact_basis":"own_site"}'::jsonb, ARRAY['needs_contact_lookup','email_missing','planner_and_florist','address_conflict_surry_hills_vs_thirroul_po_box','second_phone_02_4268_1899_south_coast']::text[]),
('florist-bold-botanicals', 'florist-bold-botanicals', 'Bold Botanicals', 'Florist', 'Inner West, Sydney NSW', NULL, 'https://www.boldbotanicals.com.au/', NULL, 'hello@boldbotanicals.com.au', 'https://www.boldbotanicals.com.au/pages/weddings', 'Florist website', '2026-11-06', 'active', 'Inner West florist known for fresh and native flowers, with luxe wedding packages from a $4,500 minimum for florals only.', '{"source":"florists_import_2026_11_06","instagram_url":"https://www.instagram.com/bold_botanicals_sydney/","price_note":"Luxe wedding packages from a $4,500 minimum, florals only.","price_from_aud":4500,"price_status":"estimated","contact_basis":"own_site"}'::jsonb, ARRAY['needs_contact_lookup','phone_missing','no_street_address','price_from_search_summary','retail_florist_with_weddings']::text[]),
('florist-rosella-floral-designs', 'florist-rosella-floral-designs', 'Rosella Floral Designs', 'Florist', 'Waitara, North Shore Sydney NSW', NULL, 'https://www.rosellafloraldesigns.com.au/', '0416 943 431', 'enquiries@rosellafloraldesigns.com.au', 'https://www.rosellafloraldesigns.com.au/about-us', 'Florist website (read via search summary)', '2026-11-06', 'active', 'Home-studio wedding and event florist in Waitara with published package prices and hire items like arches and centrepieces. Travels across Greater Sydney and out to the Hunter, Central Coast, Highlands and South Coast. Consultations by appointment.', '{"source":"florists_import_2026_11_06","instagram_url":"https://www.instagram.com/rosellafloraldesigns/","price_note":"Four wedding packages from $600 to $1,800; items from a $15 buttonhole to a $600 ceremony arch; all starting figures.","price_from_aud":600,"price_status":"estimated","contact_basis":"search_result"}'::jsonb, ARRAY['contacts_from_search_result_site_not_readable','no_street_address','price_from_search_summary','verify_travel_to_blue_mountains_paused']::text[]),
('florist-the-faux-fernery', 'florist-the-faux-fernery', 'The Faux Fernery', 'Florist', 'Middle Cove, North Shore Sydney NSW', '213 Eastern Valley Way, Middle Cove NSW 2068', 'http://www.thefauxfernery.com.au', '0408 440 660', 'info@thefauxfernery.com.au', 'https://www.thefloristquarter.com.au/directory/the-faux-fernery', 'Directory or social listing (unverified)', '2026-11-06', 'active', 'Hire business for artificial, dried and preserved wedding flowers, from ceremony arbours and ceiling installs to centrepieces. Faux blooms do not wilt in heat or rain and can be arranged ahead. Showroom by appointment.', '{"source":"florists_import_2026_11_06","instagram_url":"https://www.instagram.com/thefauxfernery/","price_note":"Hire pricing not found. One blog says it cost about half of comparable fresh flowers.","price_from_aud":null,"price_status":null,"contact_basis":"directory"}'::jsonb, ARRAY['contacts_directory_only_unverified','own_site_not_reachable_by_script','faux_flower_hire_not_fresh']::text[]),
('florist-eden-and-bell', 'florist-eden-and-bell', 'Eden & Bell', 'Florist', 'Surry Hills, Sydney NSW', '515 Crown Street, Surry Hills NSW 2010', 'https://edenandbell.com.au/', '0406 899 499', NULL, 'https://edenandbell.com.au/pages/shop', 'Florist website (read via search summary)', '2026-11-06', 'active', 'Surry Hills florist shop run by Sophie and Dom Geisser, doing wedding flowers since 2017 on top of retail and corporate work. Weddings have a minimum spend and are designed around the couple''s tastes.', '{"source":"florists_import_2026_11_06","instagram_url":null,"price_note":"Wedding work has a minimum spend, then is personalised; amount not read.","price_from_aud":null,"price_status":null,"contact_basis":"search_result"}'::jsonb, ARRAY['contacts_from_search_result_site_not_readable','needs_contact_lookup','email_missing','retail_florist_with_weddings']::text[]),
('florist-christine-and-rose', 'florist-christine-and-rose', 'Christine & Rose', 'Florist', 'Five Dock, Inner West Sydney NSW', 'Harrabrook Avenue, Five Dock NSW 2046', 'https://www.christineandrose.com.au/', '0452 447 462', 'christineandroseflowers@gmail.com', 'https://www.christineandrose.com.au/', 'Directory or social listing (unverified)', '2026-11-06', 'active', 'Studio florist in Five Dock run by Gemma Mehta, doing bespoke weddings and events by appointment with pick-up and local delivery. Quotes are custom and requested by email.', '{"source":"florists_import_2026_11_06","instagram_url":"https://www.instagram.com/christineandroseflowers/","price_note":"Custom quote by email; a directory offered 10% off via its listing.","price_from_aud":null,"price_status":null,"contact_basis":"directory"}'::jsonb, ARRAY['phone_email_from_instagram_listing_unverified','no_street_number','needs_contact_lookup']::text[]),
